import React, { useEffect, useState } from 'react';
import { getRealtime, getPlantMetrics, getAlerts } from '../api';
import PlantChart from './PlantChart';

// const [dark, setDark] = React.useState(false);

function getStatus(efficiency) {
  if (efficiency == null) return { label: 'Unknown', color: '#6b7280' };   // gray
  if (efficiency > 50) return { label: 'Healthy', color: '#16a34a' };      // green
  if (efficiency > 20) return { label: 'Warning', color: '#f59e0b' };      // yellow
  return { label: 'Critical', color: '#dc2626' };                          // red
}

export default function Dashboard(){
  const [data, setData] = useState({ plants: [], totalGen:0, totalCapacity:0, gridLoad:null });
  const [alerts, setAlerts] = useState([]);
  const [selectedPlant, setSelectedPlant] = useState(null);
  const [plantMetrics, setPlantMetrics] = useState([]);

  async function fetchAll(){
    try {
      const d = await getRealtime();
      setData(d);
      const a = await getAlerts();
      setAlerts(a.slice(0,10));
      if (d.plants && d.plants.length) setSelectedPlant(d.plants[0].plant_id);
    } catch (e) { console.error(e); }
  }

  useEffect(()=> {
    fetchAll();
    const id = setInterval(fetchAll, 5000);
    return ()=>clearInterval(id);
  }, []);

  useEffect(()=>{
    if (selectedPlant) {
      getPlantMetrics(selectedPlant, 300).then(m=>{
        setPlantMetrics(m);
      });
    }
  }, [selectedPlant]);

  return (
    <div style={{display:'grid', gridTemplateColumns:'1fr 360px', gap:20}}>
      <div>
        <button 
          onClick={() => setDark(!dark)} 
          style={{
            padding: "8px 14px",
            borderRadius: "8px",
            background: dark ? "#374151" : "#e5e7eb",
            color: dark ? "#fff" : "#111",
            border: "1px solid #999",
            cursor: "pointer",
            position: "absolute",
            top: 20,
            right: 20
          }}
        >
          {dark ? "Light Mode" : "Dark Mode"}
        </button>

        <div style={{display:'flex', gap:12, marginBottom:12}}>
          <Card title="Total Generation">{Math.round(data.totalGen)} kW</Card>
          <Card title="Total Capacity">{Math.round(data.totalCapacity)} kW</Card>
          <Card title="Grid Load">{data.gridLoad ? Math.round(data.gridLoad) + ' kW' : '---'}</Card>
          <Card title="Renewable %">
            {data.totalCapacity ? Math.round((data.totalGen / data.totalCapacity) * 100) : 0}%
          </Card>
        </div>

        <section style={{display:'grid', gridTemplateColumns:'repeat(2, 1fr)', gap:12}}>
          {data.plants.map(p => {
            const eff = p.efficiency == null ? null : Number(p.efficiency);
            const { label, color } = getStatus(eff);

            return (
              <div 
                key={p.plant_id}
                style={{ 
                  position: 'relative', 
                  padding: 12, 
                  border: '1px solid #ddd', 
                  borderRadius: 8, 
                  background: '#fff',
                  marginBottom: 16
                }}
              >
                {/* Status badge */}
                <div style={{ position: 'absolute', top: 12, right: 12 }}>
                  <span style={{
                    display: 'inline-block',
                    padding: '6px 10px',
                    borderRadius: 12,
                    color: '#fff',
                    fontSize: 12,
                    fontWeight: 600,
                    backgroundColor: color
                  }}>
                    {label}
                  </span>
                </div>

                <h3>{p.name}</h3>
                <div>Type: {p.type}</div>
                <div>Capacity: {p.capacity} kW</div>
                <div>Output: {p.output ? Math.round(p.output) + ' kW' : '—'}</div>
                {/* Generation Bar */}
                <div style={{
                  width: "100%",
                  height: "7px",
                  background: "#e5e7eb",
                  borderRadius: "4px",
                  marginTop: "6px"
                }}>
                  <div style={{
                    height: "100%",
                    width: `${(p.output && p.capacity) ? (p.output / p.capacity) * 100 : 0}%`,
                    background: "#2563eb",
                    borderRadius: "4px",
                    transition: "width 0.4s ease"
                  }}/>
                </div>
                <div>Efficiency: {eff != null ? eff.toFixed(2) + '%' : '—'}</div>

                <button 
                  style={{ marginTop: 8 }} 
                  onClick={() => setSelectedPlant(p.plant_id)}
                >
                  View details
                </button>
              </div>
            );
          })}
        </section>

        <div style={{marginTop:18}}>
          <h2>Plant Details</h2>
          {selectedPlant ? <PlantChart metrics={plantMetrics} /> : <div>Select a plant</div>}
        </div>
      </div>

      <aside style={{border:'1px solid #eee', padding:12, borderRadius:8}}>
        <h3>Alerts</h3>
        {alerts.length === 0 ? <div>No active alerts</div> : alerts.map(a=>(
          <div key={a.id} style={{padding:8,borderBottom:'1px solid #f1f1f1'}}>
            <strong>{a.severity}</strong> — {a.type}
            <div style={{fontSize:12,color:'#555'}}>{a.timestamp}</div>
            <div style={{fontSize:13}}>{a.message}</div>
          </div>
        ))}
      </aside>
    </div>
  );
}

function Card({title, children}) {
  return (
    <div style={{padding:12, border:'1px solid #e5e7eb', borderRadius:8, minWidth:120, background:'#fff'}}>
      <div style={{fontSize:12,color:'#6b7280'}}>{title}</div>
      <div style={{fontSize:18,fontWeight:600}}>{children}</div>
    </div>
  );
}
